import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Explicit-Categories.md","filePath":"manual-zh/CTABLES-Explicit-Categories.md","lastUpdated":1785684581000}'),r={name:"manual-zh/CTABLES-Explicit-Categories.md"};function p(c,t,i,n,s,_){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-5-1-显式类别" tabindex="-1">15.7.5.1 显式类别 <a class="header-anchor" href="#_15-7-5-1-显式类别" aria-label="Permalink to &quot;15.7.5.1 显式类别&quot;">​</a></h4><p>要使用 <code>CTABLES</code> 显式指定要包含的类别，请在方括号内按所需排序顺序列出类别。使用空格或逗号分隔取值。未被列表覆盖的类别将被排除在分析之外。</p><p>列表中的每个元素采用以下形式之一：</p><p><code>_number_</code><code>&#39;_string_ &#39;</code></p><p>数值或字符串类别取值，用于具有相应类型的变量。</p><p><code>&#39;_date_ &#39;</code><code>&#39;_time_ &#39;</code></p><p>日期或时间类别取值，用于具有日期或时间打印格式的变量。</p><p><code>_min_ THRU _max_</code><code>LO THRU _max_</code><code>_min_ THRU HI</code></p><p>类别取值的范围，其中 min 和 max 各自取上述形式之一，按递增顺序。</p><p><code>MISSING</code></p><p>所有用户缺失值。（要匹配单个用户缺失值，请指定其类别取值。）</p><p><code>OTHERNM</code></p><p>未被列表中任何其他元素覆盖的任何非缺失值（无论 <code>OTHERNM</code> 在列表中置于何处）。</p><p><code>&amp;_postcompute_</code></p><p>一个计算类别名（参见 <a href="./CTABLES-Computed-Categories">CTABLES Computed Categories</a>）。</p><p><code>SUBTOTAL</code><code>HSUBTOTAL</code></p><p>小计（参见 <a href="./CTABLES-Totals-and-Subtotals">CTABLES Totals and Subtotals</a>）。</p><p>如果列表中的多个元素覆盖某个给定类别，则以列表中最后一个为准。</p><p>以下示例语法和输出展示了显式类别如何限制所显示的类别：</p><pre><code>CTABLES /TABLE freqOfDriving.
CTABLES /TABLE freqOfDriving /CATEGORIES VARIABLES=freqOfDriving [1, 2, 3].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td></td><td></td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr></tbody></table>`,21)])])}const m=e(r,[["render",p]]);export{T as __pageData,m as default};
